// src/utils/feeRules.js
export function getApplicableFeeKeys(className) {
  const num = parseInt(className); // extract class number safely
  if (num >= 1 && num <= 5) {
    // 1–5: hide lab, sports, art/music/dance
    return ["tuition", "development", "transport", "exam"];
  } else if (num >= 6 && num <= 9) {
    // 6–9: hide exam fee
    return ["tuition", "development", "computer", "transport", "sports", "artMusic"];
  } else if (num >= 10 && num <= 12) {
    // 10–12: all fees visible
    return [
      "tuition",
      "development",
      "computer",
      "transport",
      "sports",
      "artMusic",
      "exam",
    ];
  }
  return ["tuition", "development", "transport"]; // fallback
}
